import numpy as np
from PIL import Image
im = np.array(Image.open('first_frame.png').convert('RGB'))
h,w,_ = im.shape
R,G,B = im[...,0].astype(int), im[...,1].astype(int), im[...,2].astype(int)

def classify(px):
    r,g,b = px
    # orange/red: r high, g mid, b low
    if r>140 and g<110 and b<90:
        return 'R'  # red/orange
    if r>180 and g>150 and b<110:
        return 'Y'  # yellow
    if b>120 and r<120 and g>80:
        return 'B'  # blue
    if r<60 and g<60 and b<60:
        return 'K'  # black
    if r>150 and g>80 and g<160 and b<80:
        return 'O'  # orange
    if abs(r-g)<20 and abs(g-b)<25:
        return '.'  # gray bg/table
    if g>r and b>r:
        return 'b' # bluish bg
    return '?'

# downsample map 256x144 -> 64x36 (4x4 blocks) majority
H,W = 36,64
small = np.empty((H,W), dtype='<U1')
for j in range(H):
    for i in range(W):
        block = im[j*4:(j+1)*4, i*4:(i+1)*4].reshape(-1,3)
        from collections import Counter
        c = Counter(classify(p) for p in block)
        small[j,i] = c.most_common(1)[0][0]
for row in small:
    print(''.join(row))
EOF"

